#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int main(void)
{
    int *p = malloc(sizeof(int));

    if (p == NULL) {
        return 1;
    }

    *p = 42;
    free(p);

    int *q = malloc(sizeof(int));

    if (q == NULL) {
        return 1;
    }

    *q = 7;

    printf("p = %p, q = %p\n", (void *)p, (void *)q);
    printf("*p = %d, *q = %d\n", *p, *q);

    free(q);

