#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int *crea_vector(int n)
{
    int *v = malloc(n * sizeof(int));

    if (v == NULL) {
        return NULL;
    }

    for (int i = 0; i &lt; n; i++) {
        v[i] = i + 1;
    }

    return v;
}

int main(void)
{
    int *v = crea_vector(5);

    if (v == NULL) {
        return 1;
    }

    for (int i = 0; i &lt; 5; i++) {
        printf("v[%d] = %d\n", i, v[i]);
    }

    free(v);

    return 0;
}
